css:
.card {
  --bg: #f2f2f2;
  --txt: #191a1b;
  --txt-sec: #7c7c7e;

  --border-col: #f7414a;
  --border: 6px;
  --shadow-alpha: 0.5; /*0-1*/
  --radius: 26px;
  --notch-h: 32px;
  --notch-w: 72px;

  --status: "2026";
  --txt-status: #e8e8e8;
  --event: "Meeting";

  position: relative;
  min-width: 120px;
  max-width: 300px;
  border-radius: var(--radius);
  box-shadow:
    0 calc(2px + var(--border)) var(--border) calc(-1 * var(--border))
      rgba(0, 0, 0, var(--shadow-alpha)),
    0 0 0 var(--border) var(--border-col);
  background-color: var(--bg);
  font-family: "Inter", "Segoe UI", sans-serif;
  font-size: 1rem;
  color: var(--txt);
  display: grid;
  grid-template-rows: var(--notch-h) 0fr auto;
  grid-template-columns: calc(100% - var(--notch-w)) var(--notch-w);
  grid-template-areas: "header" "body" "footer";
  padding: 0.75rem;
  transition:
    grid-template-rows 0.5s cubic-bezier(0.23, 1, 0.32, 1),
    row-gap 0.5s cubic-bezier(0.23, 1, 0.32, 1);
  user-select: none;
}
.card > .header {
  margin-bottom: 1rem;
}
.card::after {
  content: var(--status);
  position: absolute;
  top: 0;
  right: 0;
  width: var(--notch-w);
  height: var(--notch-h);
  display: grid;
  place-items: center;
  border-radius: 0 calc(0.9 * var(--radius));
  background-color: var(--border-col);
  text-transform: capitalize;
  font-size: 0.8rem;
  color: var(--txt-status);
}

.card .corner {
  content: "";
  position: absolute;
  width: var(--notch-h);
  height: var(--notch-h);
  background-color: var(--border-col);
  border-radius: 50% 0 50% 50%;
  mask: radial-gradient(
    circle at center,
    #0000 calc(0.5 * var(--notch-h)),
    blue calc(0.5 * var(--notch-h) + 1px)
  );
  &.c1 {
    top: 0;
    right: var(--notch-w);
  }
  &.c2 {
    top: var(--notch-h);
    right: 0;
  }
}

.card .header {
  grid-area: header;
  position: relative;
  display: flex;
  align-items: center;
  font-weight: bold;
  padding-left: 1.25rem;
  text-transform: capitalize;
}

.card .body {
  position: relative;
  grid-area: body;
  grid-column: span 2;

  z-index: 1;

  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-template-rows: repeat(6, 1fr);

  font-size: 0.9rem;
  min-height: 0;
  transition: 0.2s ease-out;
  overflow: hidden;

  .svg {
    margin: 0.5rem;
    height: 32px;
    stroke-width: 1px;
    stroke: var(--txt-sec);
    fill: none;
  }
}

.card .body::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 1px;
  background-color: #0000;
  transition: background-color 0.3 ease;
  top: -0.5rem;
}

.card .header .input-expand {
  position: absolute;
  inset: 0;
  margin: 0;
  border: none;
  appearance: none;
  cursor: pointer;
}

.card .header .input-expand::after {
  content: "";
  pointer-events: none;
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  background-image: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIGZpbGw9Im5vbmUiIHZpZXdCb3g9IjAgMCAyNCAyNCIgc3Ryb2tlLXdpZHRoPSIxLjUiIHN0cm9rZT0iY3VycmVudENvbG9yIj4KICA8cGF0aCBzdHJva2UtbGluZWNhcD0icm91bmQiIHN0cm9rZS1saW5lam9pbj0icm91bmQiIGQ9Im0xOS41IDguMjUtNy41IDcuNS03LjUtNy41IiAvPgo8L3N2Zz4=");
  background-repeat: no-repeat;
  transition: transform 0.3s ease;
  transform: rotate(-90deg);
}

.card:has(.header .input-expand:checked) {
  grid-template-rows: var(--notch-h) 1fr auto;
  .body {
    padding-bottom: 1rem;
  }
  .body::before {
    background-color: #000;
  }
}

.card .header .input-expand:checked::after {
  transform: rotate(0deg);
}

.card .footer {
  grid-area: footer;
  grid-column: span 2;
  color: var(--txt-sec);
  font-size: 0.8rem;

  display: grid;
  grid-template-columns: 1fr;
}
.card .footer .event-entry {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
}

.day,
.date {
  position: relative;
  display: flex;
  align-items: center;
  padding: 0.1rem 0.25rem;
  justify-content: center;
  color: var(--txt-sec);
  transition: 0.3s ease;
}
.day {
  font-size: 0.75rem;
}
.date {
  color: var(--txt-sec);
  cursor: help;
}

.date:hover {
  color: var(--txt);
}

.date.today {
  font-weight: bold;
  color: var(--bg);
}
.date.today::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: 5px;
  background-color: var(--border-col);
  mix-blend-mode: darken;
}

.date.event {
  font-weight: bold;
  color: var(--border-col);
}

.date.event:hover::after {
  content: var(--event);
  position: absolute;
  padding: 0.25rem 0.75rem;
  border-radius: 5px;
  width: fit-content;
  background-color: rgba(0, 0, 0, 0.7);
  color: var(--bg);
  top: -100%;
}
